&lt;p style=&quot;line-height: 1;&quot; data-start=&quot;3969&quot; data-end=&quot;3980&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Sponsorship&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
