&lt;/ul&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559685&amp;quot;:1440}&quot;&gt;&lt;br&gt;&amp;nbsp;T&lt;/span&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;echnical Ownership&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;Aptos&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335551671&amp;quot;:0,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:1440,&amp;quot;335559991&amp;quot;:720,&amp;quot;469769226&amp;quot;:&amp;quot;Aptos&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;5&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Own verification planning, execution and sign off for all RTL blocks and top-level SoCs.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;Aptos&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335551671&amp;quot;:0,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:1440,&amp;quot;335559991&amp;quot;:720,&amp;quot;469769226&amp;quot;:&amp;quot;Aptos&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;6&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Oversee definition of test plans&amp;nbsp;including functional coverage targets. Drive close through prioritisation of test content and coverage signoff. Iterate plans to close verification gaps.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
