&lt;li id=&quot;p-rc_beded5010ce8b3c4-23&quot;&gt;
&lt;p id=&quot;p-rc_beded5010ce8b3c4-26&quot; data-path-to-node=&quot;13,2,0&quot;&gt;&lt;span class=&quot;citation-595 citation-end-595&quot;&gt;Une équipe de projet locale au sein d&#39;un réseau mondial (possibilité de carrière internationale) ;&lt;sup class=&quot;superscript&quot; data-turn-source-index=&quot;2&quot;&gt;&lt;/sup&gt;&lt;/span&gt; &lt;/p&gt;
